import { useState } from 'react';

const fakeAttendance = [
  { id: 1, name: 'Nguyễn Văn An', date: '22/05/2026', checkIn: '08:02', checkOut: '17:10', status: 'Đúng giờ' },
  { id: 2, name: 'Trần Thị Bình', date: '22/05/2026', checkIn: '08:45', checkOut: '17:00', status: 'Đi muộn' },
  { id: 3, name: 'Lê Văn Cường', date: '22/05/2026', checkIn: '--', checkOut: '--', status: 'Nghỉ phép' },
  { id: 4, name: 'Phạm Thị Dung', date: '22/05/2026', checkIn: '07:55', checkOut: '17:05', status: 'Đúng giờ' },
  { id: 5, name: 'Hoàng Văn Em', date: '22/05/2026', checkIn: '09:10', checkOut: '17:30', status: 'Đi muộn' },
];

function statusBadge(status) {
  if (status === 'Đúng giờ') return <span className="badge bg-success">{status}</span>;
  if (status === 'Đi muộn') return <span className="badge bg-warning text-dark">{status}</span>;
  if (status === 'Nghỉ phép') return <span className="badge bg-secondary">{status}</span>;
  return <span className="badge bg-danger">{status}</span>;
}

function Attendance() {
  const [selectedDate, setSelectedDate] = useState('22/05/2026');

  return (
    <div>
      <h4 className="mb-1">Chấm công</h4>
      <p className="text-muted mb-3" style={{ fontSize: '14px' }}>
        Theo dõi thời gian ra vào của nhân viên.
      </p>

      {/* Lọc ngày */}
      <div className="row mb-3">
        <div className="col-md-3">
          <div className="d-flex align-items-center gap-2">
            <label className="form-label mb-0 text-nowrap">Ngày:</label>
            <input
              type="text"
              className="form-control"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Bảng chấm công */}
      <div className="card">
        <div className="card-body p-0">
          <table className="table table-bordered table-striped table-hover mb-0">
            <thead className="table-light">
              <tr>
                <th>STT</th>
                <th>Họ tên</th>
                <th>Ngày</th>
                <th>Giờ vào</th>
                <th>Giờ ra</th>
                <th>Trạng thái</th>
              </tr>
            </thead>
            <tbody>
              {fakeAttendance.map((row, index) => (
                <tr key={row.id}>
                  <td>{index + 1}</td>
                  <td>{row.name}</td>
                  <td>{row.date}</td>
                  <td>{row.checkIn}</td>
                  <td>{row.checkOut}</td>
                  <td>{statusBadge(row.status)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default Attendance;
